PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE event_sequence (
    id           INTEGER PRIMARY KEY,
    kind         TEXT NOT NULL CHECK (kind <> ''),
    logical_id   TEXT NOT NULL CHECK (logical_id <> ''),
    uid          TEXT NOT NULL UNIQUE,
    seq          INTEGER NOT NULL CHECK (seq >= 1),
    start_commit INTEGER,
    owner_id     TEXT,
    parent_id    INTEGER REFERENCES event_sequence(id) ON DELETE CASCADE,
    closed_by    INTEGER,
    UNIQUE (kind, logical_id)
  ) STRICT;
CREATE TABLE blob (
    digest TEXT PRIMARY KEY CHECK (length(digest) = 64),
    value  BLOB NOT NULL
  ) STRICT;
CREATE TABLE event (
    "commit"  INTEGER PRIMARY KEY AUTOINCREMENT,
    aggregate INTEGER NOT NULL REFERENCES event_sequence(id) ON DELETE CASCADE,
    seq       INTEGER NOT NULL,
    type      TEXT NOT NULL,
    version   INTEGER NOT NULL CHECK (version >= 1),
    origin    TEXT NOT NULL,
    at        INTEGER NOT NULL,
    data      TEXT NOT NULL,
    UNIQUE (aggregate, seq)
  ) STRICT;
CREATE TABLE event_blob (
    "commit" INTEGER NOT NULL REFERENCES event("commit") ON DELETE CASCADE,
    digest   TEXT NOT NULL REFERENCES blob(digest),
    PRIMARY KEY ("commit", digest)
  ) STRICT, WITHOUT ROWID;
CREATE TABLE stored_kind (
    type    TEXT PRIMARY KEY,
    version INTEGER NOT NULL
  ) STRICT, WITHOUT ROWID;
CREATE TABLE current_value (
    family  TEXT NOT NULL,
    key     TEXT NOT NULL,
    version INTEGER NOT NULL CHECK (version >= 1),
    value   TEXT NOT NULL,
    at      INTEGER NOT NULL,
    PRIMARY KEY (family, key)
  ) STRICT, WITHOUT ROWID;
CREATE TABLE input_history (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    at    INTEGER NOT NULL,
    value TEXT NOT NULL
  ) STRICT;
CREATE TABLE aggregate_change (change INTEGER PRIMARY KEY
    AUTOINCREMENT, kind TEXT NOT NULL, logical_id TEXT NOT NULL,
    UNIQUE (kind, logical_id)) STRICT;
CREATE TABLE projection_state (
    name           TEXT PRIMARY KEY,
    version        INTEGER NOT NULL,
    through_commit INTEGER NOT NULL
  ) STRICT, WITHOUT ROWID;
CREATE TABLE projected_row (
    "commit" INTEGER NOT NULL REFERENCES event("commit") ON DELETE CASCADE,
    type     TEXT NOT NULL,
    data     TEXT NOT NULL,
    PRIMARY KEY ("commit", type)
  ) STRICT, WITHOUT ROWID;
CREATE TABLE listing_entry (
    aggregate INTEGER NOT NULL REFERENCES event_sequence(id) ON DELETE CASCADE,
    key       TEXT NOT NULL,
    "commit"  INTEGER NOT NULL,
    PRIMARY KEY (aggregate, key)
  ) STRICT, WITHOUT ROWID;
CREATE TABLE run_usage (
    aggregate INTEGER PRIMARY KEY REFERENCES event_sequence(id) ON DELETE CASCADE,
    "commit"  INTEGER NOT NULL,
    usage     TEXT NOT NULL
  ) STRICT;
DELETE FROM sqlite_sequence;
CREATE INDEX event_sequence_parent
    ON event_sequence(parent_id) WHERE parent_id IS NOT NULL;
CREATE INDEX event_aggregate_type ON event(aggregate, type, seq);
CREATE INDEX event_type_commit ON event(type, "commit");
CREATE INDEX event_blob_digest ON event_blob(digest);
CREATE INDEX current_value_at ON current_value(family, at);
CREATE TRIGGER aggregate_inserted
    AFTER INSERT ON event_sequence BEGIN INSERT OR REPLACE INTO aggregate_change
    (kind, logical_id) VALUES (NEW.kind, NEW.logical_id); END;
CREATE TRIGGER aggregate_claimed
    AFTER UPDATE OF owner_id, closed_by ON event_sequence BEGIN INSERT OR REPLACE INTO aggregate_change
    (kind, logical_id) VALUES (NEW.kind, NEW.logical_id); END;
CREATE TRIGGER aggregate_collected
    AFTER DELETE ON event_sequence BEGIN INSERT OR REPLACE INTO aggregate_change
    (kind, logical_id) VALUES (OLD.kind, OLD.logical_id); END;
PRAGMA user_version=101;
PRAGMA application_id=1415927890;
COMMIT;
